import hashlib
import hmac
import os
import time
from typing import Dict, Optional, Any
from dataclasses import dataclass, field


@dataclass
class FeatureFlag:
    name: str
    enabled: bool
    rollout_percentage: int = 100
    cache_ttl: int = 300


@dataclass
class CacheEntry:
    value: bytes
    mac: bytes
    expires_at: float
    namespace: str


class KeyDerivation:
    """Derives per-namespace keys from a master secret."""

    def __init__(self, master_secret: bytes):
        self._master = master_secret
        self._derived_cache: Dict[str, bytes] = {}

    def derive_key(self, namespace: str, purpose: str) -> bytes:
        """Derive a key for a specific namespace and purpose."""
        cache_key = f"{namespace}:{purpose}"
        if cache_key not in self._derived_cache:
            # HKDF-like derivation
            prk = hmac.new(self._master, namespace.encode(), hashlib.sha256).digest()
            okm = hmac.new(prk, purpose.encode(), hashlib.sha256).digest()
            self._derived_cache[cache_key] = okm
        return self._derived_cache[cache_key]


class DistributedCacheClient:
    """Client for distributed cache with integrity verification."""

    def __init__(self, master_secret: bytes, feature_flags: Dict[str, FeatureFlag]):
        self._kdf = KeyDerivation(master_secret)
        self._flags = feature_flags
        self._local_store: Dict[str, CacheEntry] = {}
        self._integrity_enabled = self._flags.get("cache_integrity", FeatureFlag("cache_integrity", True)).enabled
        self._namespace_isolation = self._flags.get("namespace_isolation", FeatureFlag("namespace_isolation", True)).enabled

    def _get_signing_key(self, namespace: str) -> bytes:
        """Get the signing key for MAC computation."""
        if self._namespace_isolation:
            return self._kdf.derive_key(namespace, "signing")
        # Fallback: use a single derived key for all namespaces
        return self._kdf.derive_key("global", "signing")

    def _get_encryption_context(self, namespace: str) -> bytes:
        """Get encryption context for authenticated encryption."""
        if self._namespace_isolation:
            return self._kdf.derive_key(namespace, "encryption")
        return self._kdf.derive_key("global", "encryption")

    def _compute_mac(self, key: bytes, data: bytes, context: bytes) -> bytes:
        """Compute MAC over data with associated context."""
        msg = context + len(data).to_bytes(8, 'big') + data
        return hmac.new(key, msg, hashlib.sha256).digest()

    def put(self, namespace: str, cache_key: str, value: bytes, ttl: Optional[int] = None) -> bool:
        """Store a value in the cache with integrity protection."""
        if ttl is None:
            flag = self._flags.get(namespace, FeatureFlag(namespace, True))
            ttl = flag.cache_ttl

        signing_key = self._get_signing_key(namespace)
        enc_context = self._get_encryption_context(namespace)

        full_key = f"{namespace}:{cache_key}"
        mac = self._compute_mac(signing_key, value, enc_context)

        entry = CacheEntry(
            value=value,
            mac=mac,
            expires_at=time.time() + ttl,
            namespace=namespace
        )
        self._local_store[full_key] = entry
        return True

    def get(self, namespace: str, cache_key: str) -> Optional[bytes]:
        """Retrieve and verify a cached value."""
        full_key = f"{namespace}:{cache_key}"
        entry = self._local_store.get(full_key)

        if entry is None:
            return None

        if time.time() > entry.expires_at:
            del self._local_store[full_key]
            return None

        if self._integrity_enabled:
            signing_key = self._get_signing_key(namespace)
            enc_context = self._get_encryption_context(namespace)
            expected_mac = self._compute_mac(signing_key, entry.value, enc_context)

            if not hmac.compare_digest(expected_mac, entry.mac):
                del self._local_store[full_key]
                return None

        return entry.value

    def migrate_namespace(self, old_ns: str, new_ns: str) -> int:
        """Migrate entries from one namespace to another, re-keying MACs."""
        migrated = 0
        keys_to_migrate = [
            k for k, v in self._local_store.items()
            if v.namespace == old_ns
        ]

        for full_key in keys_to_migrate:
            entry = self._local_store[full_key]
            cache_key = full_key.split(":", 1)[1]

            # Re-sign with new namespace key
            new_signing_key = self._get_signing_key(new_ns)
            new_enc_context = self._get_encryption_context(new_ns)
            new_mac = self._compute_mac(new_signing_key, entry.value, new_enc_context)

            new_full_key = f"{new_ns}:{cache_key}"
            self._local_store[new_full_key] = CacheEntry(
                value=entry.value,
                mac=new_mac,
                expires_at=entry.expires_at,
                namespace=new_ns
            )
            del self._local_store[full_key]
            migrated += 1

        return migrated


def create_client(config: Dict[str, Any]) -> DistributedCacheClient:
    """Factory function to create cache client from config."""
    master_secret = config.get("master_secret", os.urandom(32))
    if isinstance(master_secret, str):
        master_secret = master_secret.encode()

    flags = {}
    for flag_config in config.get("feature_flags", []):
        flag = FeatureFlag(
            name=flag_config["name"],
            enabled=flag_config.get("enabled", True),
            rollout_percentage=flag_config.get("rollout_percentage", 100),
            cache_ttl=flag_config.get("cache_ttl", 300)
        )
        flags[flag.name] = flag

    return DistributedCacheClient(master_secret, flags)
